import {state,esc} from '../../lib/store.js';import {panel,tabs,badge,button,input,area,empty} from '../pixel/primitives.js';
import {newsView} from './live-news.js';import {translationView,historyView} from './translation.js';
export function trainingGoalForm(){const goal=state.trainingGoal||{};return `<form data-form="training-goal" class="training-goal-form"><div class="formgrid">${input('title','目标名称',goal.title||'','text','maxlength="120" placeholder="例如：CAPLE C1"')}${input('status','当前状态',goal.status||'','text','maxlength="120" placeholder="例如：备考中"')}${input('targetDate','目标日期（可选）',goal.targetDate||'','date')}</div><div class="actions"><button class="button primary" type="submit">保存学习目标</button>${button('取消','close')}</div></form>`}
function trainingGoalBar(){const goal=state.trainingGoal||{},hasTitle=Boolean(goal.title);return `<section class="training-goal-bar" aria-label="学习目标"><div><span>LEARNING GOAL / 学习目标</span>${hasTitle?`<strong>${esc(goal.title)}</strong>${goal.status?`<small>${esc(goal.status)}</small>`:''}${goal.targetDate?`<small>目标日期 · ${esc(goal.targetDate)}</small>`:''}`:'<strong>设定学习目标</strong><small>为当前本地用户设置独立学习目标</small>'}</div>${button(hasTitle?'编辑目标':'设置目标','training-goal','','small')}</section>`}
export function training(ui){let content='';if(ui.training==='news')content=newsView(ui);
if(ui.training==='vocab')content=`<div class="row wrap mb"><p class="muted">个人词库 · ${state.vocab.filter(v=>v.saved).length} 已收藏</p><div class="actions">${button(ui.vocabSaved?'显示全部':'只看收藏','vocab-filter')}${button('＋ 添加表达','vocab-new','','primary')}</div></div><div class="word-grid">${state.vocab.filter(v=>!ui.vocabSaved||v.saved).map(v=>wordCard(v)).join('')||empty('还没有收藏的表达。')}</div>`;
if(ui.training==='translation')content=translationView(ui)+(state.legacyDraft?`<details class="mt"><summary>V0.1 保留的翻译草稿</summary><p class="muted">原练习：学习一门语言，也是在学习另一种观察世界的方式。</p><p class="pre">${esc(state.legacyDraft)}</p></details>`:'');
if(ui.training==='history')content=historyView(ui);
return trainingGoalBar()+tabs([['news',"TODAY'S PORTUGUESE"],['vocab','VOCABULARY'],['translation','TRANSLATION'],['history','HISTORY']],ui.training,'training')+content}
export function wordCard(v){return `<article class="panel word"><div class="row"><h3>${esc(v.word)}</h3>${button(v.saved?'★ 已收藏':'☆ 收藏','vocab-star',`data-id="${v.id}" aria-pressed="${v.saved}"`,'small')}</div><p class="muted micro">${esc(v.pos)} / ${esc(v.register)}</p><p>${esc(v.zh)}</p><dl><dt>DEFINIÇÃO</dt><dd lang="pt">${esc(v.pt)}</dd><dt>ORIGINAL SENTENCE</dt><dd lang="pt">${esc(v.sentence)}</dd><dt>COLLOCATIONS / SYNONYMS</dt><dd>${esc(v.collocation)}<br>${esc(v.synonyms)}</dd><dt>C1 USAGE NOTE</dt><dd>${esc(v.c1)}</dd></dl><div class="row wrap mt"><span class="micro muted">${esc(v.tags)} · 复习 ${v.reviews||0} 次</span>${button('复习卡片','vocab-review',`data-id="${v.id}"`,'small')}</div></article>`}
export function vocabForm(){return `<form data-form="vocab"><div class="formgrid">${input('word','Word / Expression','','text','required')}${input('pos','Part of Speech')}${input('zh','中文释义','','text','required')}${input('pt','Definition in Portuguese')}${area('sentence','Original Sentence')}${area('collocation','Collocations')}${input('synonyms','Synonyms')}${input('register','Register')}${area('c1','C1 Usage Note')}${input('tags','Tags')}</div><button class="button primary">加入个人词库</button></form>`}
